import { api } from './api.min.js?v=20261019_1';
import { addDays, todayISO } from '/shared/week.min.js?v=20261019_1';

export const store = {
  user: null,
  group: null,
  meta: { demo: false, lessonTypes: [] },
  lessons: null,
  selectedDate: todayISO(),
  weekOverride: null,
  mobilePane: 'lessons',
  todoSubject: null,
};

export function setSession({ user, group }) {
  const groupChanged = store.group?.id !== group?.id;
  store.user = user;
  store.group = group;
  if (groupChanged) store.lessons = null;
}

export function clearSession() {
  store.user = null;
  store.group = null;
  store.lessons = null;
  tasks.reset();
}

export async function ensureLessons(force = false) {
  if (store.lessons && !force) return store.lessons;
  const data = await api.get('/api/schedule');
  store.lessons = data.lessons;
  store.group = { ...store.group, ...data.group };
  return store.lessons;
}

export function lessonsOf(day, week) {
  return (store.lessons || [])
    .filter((l) => l.day === day && (l.week === 0 || l.week === week))
    .sort((a, b) => a.start.localeCompare(b.start));
}

const byDone = (a, b) => Number(a.done) - Number(b.done) || a.id - b.id;

export const tasks = {
  byDate: new Map(),
  weeks: new Set(),
  allLoaded: false,

  reset() {
    this.byDate.clear();
    this.weeks.clear();
    this.allLoaded = false;
    this.pendingApproval = false;
  },

  put(task) {
    const list = this.byDate.get(task.date) || [];
    list.push(task);
    this.byDate.set(task.date, list);
  },

  async loadWeek(monday) {
    if (this.allLoaded || this.weeks.has(monday)) return;
    const res = await api.get(`/api/tasks?from=${monday}&to=${addDays(monday, 6)}`);
    const rows = res?.tasks || [];
    this.pendingApproval = Boolean(res?.pendingApproval);
    for (let i = 0; i < 7; i++) this.byDate.set(addDays(monday, i), []);
    rows.forEach((t) => this.put(t));
    this.weeks.add(monday);
  },

  async loadAll() {
    const res = await api.get('/api/tasks');
    const rows = res?.tasks || [];
    this.pendingApproval = Boolean(res?.pendingApproval);
    this.byDate.clear();
    rows.forEach((t) => this.put(t));
    this.allLoaded = true;
  },

  list(date) {
    return [...(this.byDate.get(date) || [])].sort(byDone);
  },

  all() {
    return [...this.byDate.values()].flat();
  },

  find(id) {
    return this.all().find((t) => t.id === id);
  },

  async add(date, text, subject, isGroup = false) {
    const { task } = await api.post('/api/tasks', {
      date,
      text,
      subject: subject || undefined,
      isGroup: Boolean(isGroup) || undefined,
    });
    this.put(task);
    return task;
  },

  async update(id, fields) {
    const task = this.find(id);
    if (!task) return null;
    const old = { ...task };
    Object.assign(task, fields);
    try {
      const res = await api.patch(`/api/tasks/${id}`, fields);
      if (res?.task) Object.assign(task, res.task);
      return task;
    } catch (err) {
      Object.assign(task, old);
      throw err;
    }
  },

  async toggle(id) {
    const task = this.find(id);
    if (!task) return null;
    task.done = !task.done;
    try {
      await api.patch(`/api/tasks/${id}`, { done: task.done });
    } catch (err) {
      task.done = !task.done;
      throw err;
    }
    return task;
  },

  async remove(id) {
    const task = this.find(id);
    if (!task) return;
    const list = this.byDate.get(task.date);
    const index = list.indexOf(task);
    list.splice(index, 1);
    try {
      await api.del(`/api/tasks/${id}`);
    } catch (err) {
      list.splice(index, 0, task);
      throw err;
    }
  },
};
